                                            if (op.sourcePunchId === punch.id) return true;

                                            // 2. Fallback to geometric match if ID missing (shouldn't happen with new logic)
                                            // Calculate global pos for this specific punch
                                            const px = pp.x + (punch.x * cos - punch.y * sin);
                                            const py = pp.y + (punch.x * sin + punch.y * cos);
                                            const tol = 2.0; // relaxed tolerance
                                            return Math.abs(op.x - px) < tol && Math.abs(op.y - py) < tol && op.toolId === punch.toolId;
                                        });

                                        if (opIndex !== -1) {
                                            if (opIndex < simulationStep) simStatus = 'done';
                                            else if (opIndex === simulationStep) simStatus = 'active';
                                            else simStatus = 'pending';
                                        }
                                    }

