                            </g>
                        )
                    })}

                    {renderOptimizedPath()}
                    {renderOptimizedHead()}
                </g>
            </svg>
        );
    }

    return (
        <main className="flex-1 bg-gray-800 flex flex-col relative">
            {mode === AppMode.PartEditor && (
                <div className="flex-none bg-gray-700/50 p-2 flex items-center space-x-4">
