                                <path d={activePart.geometry.path} fill="rgba(31, 41, 55, 0.5)" stroke="#63b3ed" strokeWidth="2" vectorEffect="non-scaling-stroke" />
                                {teachMode && renderTeachModeHighlights()}
                                {activePart.punches.map(punch => {
